public class UserSearch {
    public ResultSet searchUser(Connection conn, String userId) throws SQLException {
        // Constructing SQL query with string concatenation is vulnerable to SQL injection
        String query = "SELECT * FROM users WHERE username = '" + userId + "'";
        Statement stmt = conn.createStatement();
        return stmt.executeQuery(query);
    }
}
